mkdir -p /app/output && cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search local doctors, dentists, and specialists. Read verified reviews and book same-day appointments in minutes with MedBook." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <style>
    :root {
      --bg: oklch(0.99 0.005 250);
      --surface: oklch(1 0 0);
      --surface-alt: oklch(0.97 0.01 240);
      --text: oklch(0.24 0.02 255);
      --muted: oklch(0.50 0.03 250);
      --primary: oklch(0.58 0.23 262);
      --primary-strong: oklch(0.52 0.25 262);
      --accent: oklch(0.72 0.15 182);
      --border: oklch(0.89 0.015 250);
      --shadow: 0 8px 30px oklch(0.45 0.05 250 / 0.08);
      --shadow-soft: 0 6px 16px oklch(0.40 0.03 250 / 0.06);
      --radius: 16px;
      --radius-sm: 12px;
    }

    * { box-sizing: border-box; }

    html, body {
      margin: 0;
      padding: 0;
      font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      background: linear-gradient(180deg, oklch(0.98 0.01 250), oklch(0.995 0.004 250));
      color: var(--text);
      scroll-behavior: smooth;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(1120px, calc(100% - 2rem));
      margin-inline: auto;
    }

    .topbar {
      position: sticky;
      top: 0;
      z-index: 30;
      backdrop-filter: blur(8px);
      background: oklch(1 0 0 / 0.84);
      border-bottom: 1px solid oklch(0.90 0.01 250 / 0.85);
    }

    .nav-wrap {
      min-height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .logo {
      display: inline-flex;
      align-items: center;
      gap: 0.55rem;
      font-weight: 800;
      font-size: 1.2rem;
      letter-spacing: -0.02em;
      color: var(--primary-strong);
    }

    .logo-badge {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      display: grid;
      place-items: center;
      color: #fff;
      background: linear-gradient(140deg, var(--primary), oklch(0.64 0.18 205));
      box-shadow: var(--shadow-soft);
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.2rem;
      font-weight: 500;
    }

    .nav-links a {
      color: var(--muted);
      transition: color .18s ease;
    }

    .nav-links a:hover,
    .nav-links a:focus-visible { color: var(--primary-strong); }

    .btn {
      border: none;
      border-radius: 999px;
      padding: .72rem 1.1rem;
      font-weight: 600;
      font-size: .95rem;
      cursor: pointer;
      transition: transform .13s ease, box-shadow .2s ease, background .2s ease;
      min-height: 44px;
    }

    .btn:active { transform: scale(.98); }

    .btn-primary {
      color: #fff;
      background: linear-gradient(145deg, var(--primary), var(--primary-strong));
      box-shadow: 0 10px 20px oklch(0.58 0.2 262 / 0.25);
    }

    .btn-primary:hover { transform: translateY(-1px); }

    .btn-ghost {
      background: transparent;
      color: var(--muted);
      border: 1px solid var(--border);
    }

    .mobile-menu-btn {
      display: none;
      border: 1px solid var(--border);
      width: 44px;
      height: 44px;
      border-radius: 12px;
      background: var(--surface);
      color: var(--text);
      cursor: pointer;
    }

    .mobile-drawer {
      position: fixed;
      inset: 0 0 0 auto;
      width: min(86vw, 330px);
      background: var(--surface);
      border-left: 1px solid var(--border);
      box-shadow: -14px 0 30px oklch(0.3 0.02 250 / 0.12);
      transform: translateX(100%);
      transition: transform .28s ease;
      z-index: 60;
      padding: 1.25rem;
      display: flex;
      flex-direction: column;
      gap: 1rem;
    }

    .mobile-drawer.open { transform: translateX(0); }

    .drawer-overlay {
      position: fixed;
      inset: 0;
      background: rgba(17, 24, 39, 0.34);
      opacity: 0;
      pointer-events: none;
      transition: opacity .2s ease;
      z-index: 55;
    }

    .drawer-overlay.show {
      opacity: 1;
      pointer-events: auto;
    }

    .hero {
      padding: 4rem 0 1rem;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.05fr .95fr;
      gap: 2rem;
      align-items: center;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: .45rem;
      background: oklch(0.95 0.04 245);
      color: var(--primary-strong);
      border-radius: 999px;
      padding: .45rem .8rem;
      font-weight: 600;
      font-size: .82rem;
      margin-bottom: 1rem;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4.6vw, 3.55rem);
      line-height: 1.06;
      letter-spacing: -0.03em;
    }

    .hero p {
      color: var(--muted);
      font-size: clamp(1rem, 1.25vw, 1.1rem);
      line-height: 1.65;
      margin: 1rem 0 1.6rem;
      max-width: 58ch;
    }

    .hero-art {
      background: radial-gradient(circle at 30% 20%, oklch(0.93 0.06 245), transparent 40%), linear-gradient(145deg, #fff, oklch(0.97 0.01 240));
      border: 1px solid var(--border);
      border-radius: 28px;
      box-shadow: var(--shadow);
      padding: 1.2rem;
    }

    .art-card {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 18px;
      padding: 1rem;
      box-shadow: var(--shadow-soft);
      margin-bottom: .9rem;
    }

    .art-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: .8rem;
      font-size: .94rem;
      color: var(--muted);
    }

    .dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: var(--accent);
      box-shadow: 0 0 0 7px oklch(0.89 0.1 182 / 0.35);
    }

    .search-wrap {
      margin-top: 1.2rem;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 24px;
      padding: .9rem;
      box-shadow: var(--shadow);
      position: relative;
    }

    .search-grid {
      display: grid;
      grid-template-columns: 1.35fr .9fr auto;
      gap: .7rem;
    }

    .input-group {
      position: relative;
      display: flex;
      align-items: center;
      gap: .55rem;
      border: 1px solid var(--border);
      background: #fff;
      border-radius: 14px;
      padding: .75rem .8rem;
      min-height: 56px;
    }

    .input-group input {
      border: 0;
      outline: none;
      width: 100%;
      font-size: 1rem;
      color: var(--text);
      background: transparent;
    }

    .suggestions {
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      right: 0;
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 14px;
      box-shadow: var(--shadow);
      overflow: hidden;
      display: none;
      z-index: 20;
    }

    .suggestions.show { display: block; }

    .suggestion-item {
      width: 100%;
      text-align: left;
      background: transparent;
      border: 0;
      padding: .75rem .9rem;
      cursor: pointer;
      font-size: .96rem;
      color: var(--text);
      transition: background .15s ease;
    }

    .suggestion-item:hover,
    .suggestion-item:focus-visible { background: oklch(0.97 0.015 250); }

    .section {
      padding: 4rem 0;
    }

    .section h2 {
      margin: 0 0 .7rem;
      font-size: clamp(1.5rem, 3vw, 2.2rem);
      letter-spacing: -0.02em;
    }

    .section .lead {
      margin: 0 0 1.5rem;
      color: var(--muted);
      max-width: 68ch;
      line-height: 1.65;
    }

    .card-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .specialty-card {
      display: block;
      background: #fff;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1.05rem;
      box-shadow: var(--shadow-soft);
      transition: transform .18s ease, box-shadow .2s ease, border-color .2s ease;
    }

    .specialty-card:hover,
    .specialty-card:focus-visible {
      transform: translateY(-3px);
      border-color: oklch(0.81 0.08 245);
      box-shadow: 0 14px 28px oklch(0.4 0.03 250 / 0.10);
    }

    .spec-head {
      display: flex;
      align-items: center;
      gap: .65rem;
      margin-bottom: .45rem;
      font-weight: 700;
    }

    .icon-chip {
      width: 38px;
      height: 38px;
      border-radius: 11px;
      display: grid;
      place-items: center;
      color: var(--primary-strong);
      background: oklch(0.95 0.04 245);
    }

    .stats {
      background: linear-gradient(145deg, var(--primary), oklch(0.61 0.2 228));
      color: #fff;
      border-radius: 20px;
      padding: 1rem;
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: .75rem;
      box-shadow: 0 18px 30px oklch(0.58 0.2 260 / 0.26);
    }

    .stat {
      background: rgba(255, 255, 255, 0.12);
      border: 1px solid rgba(255, 255, 255, 0.22);
      border-radius: 14px;
      padding: .9rem;
    }

    .stat strong { display: block; font-size: 1.35rem; }

    .steps {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .step {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1rem;
      box-shadow: var(--shadow-soft);
    }

    .step .num {
      width: 34px;
      height: 34px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      font-weight: 700;
      color: var(--primary-strong);
      background: oklch(0.95 0.04 245);
      margin-bottom: .7rem;
    }

    .testimonials {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .quote {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1rem;
      box-shadow: var(--shadow-soft);
      color: var(--muted);
      line-height: 1.6;
    }

    .quote b {
      color: var(--text);
      display: block;
      margin-top: .8rem;
      font-size: .92rem;
    }

    .app-promo {
      background: linear-gradient(155deg, oklch(0.97 0.02 245), #fff);
      border: 1px solid var(--border);
      border-radius: 22px;
      box-shadow: var(--shadow);
      padding: 1.2rem;
      display: grid;
      grid-template-columns: 1.2fr .8fr;
      gap: 1rem;
      align-items: center;
    }

    .store-buttons { display: flex; gap: .75rem; flex-wrap: wrap; margin-top: 1rem; }

    .store {
      border: 1px solid var(--border);
      border-radius: 12px;
      background: #fff;
      padding: .65rem .9rem;
      font-weight: 600;
      min-height: 44px;
      display: inline-flex;
      align-items: center;
      gap: .5rem;
    }

    footer {
      margin-top: 4rem;
      background: oklch(0.19 0.02 255);
      color: oklch(0.9 0.01 255);
      padding: 2.4rem 0 1.2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .footer-col h3 {
      margin: 0 0 .6rem;
      color: #fff;
      font-size: 1rem;
    }

    .footer-col a {
      display: block;
      color: oklch(0.82 0.01 255);
      margin: .35rem 0;
      font-size: .94rem;
    }

    .footer-end {
      border-top: 1px solid oklch(0.35 0.02 255);
      margin-top: 1.2rem;
      padding-top: .9rem;
      color: oklch(0.78 0.01 255);
      font-size: .92rem;
    }

    @media (max-width: 980px) {
      .hero-grid,
      .app-promo { grid-template-columns: 1fr; }
      .card-grid,
      .steps,
      .testimonials,
      .stats,
      .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .search-grid { grid-template-columns: 1fr; }
    }

    @media (max-width: 760px) {
      .nav-links { display: none; }
      .mobile-menu-btn { display: inline-grid; place-items: center; }
      .hero { padding-top: 2rem; }
      .card-grid,
      .steps,
      .testimonials,
      .stats,
      .footer-grid { grid-template-columns: 1fr; }
      .container { width: min(1120px, calc(100% - 1.25rem)); }
      .search-wrap { border-radius: 16px; }
    }

    @media (prefers-reduced-motion: reduce) {
      * { transition: none !important; animation: none !important; scroll-behavior: auto !important; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="container nav-wrap">
      <a href="index.html" class="logo" aria-label="MedBook home">
        <span class="logo-badge"><i data-lucide="heart-pulse" aria-hidden="true"></i></span>
        MedBook
      </a>
      <nav class="nav-links" aria-label="Primary navigation">
        <a href="#specialties">Browse</a>
        <a href="#footer">Help</a>
        <a href="#" aria-label="Log in">Log In</a>
        <button class="btn btn-primary" type="button">Sign Up</button>
      </nav>
      <button class="mobile-menu-btn" id="menuToggle" aria-label="Open menu" aria-controls="mobileDrawer" aria-expanded="false">
        <i data-lucide="menu" aria-hidden="true"></i>
      </button>
    </div>
  </header>

  <div class="drawer-overlay" id="drawerOverlay"></div>
  <aside class="mobile-drawer" id="mobileDrawer" aria-label="Mobile navigation drawer">
    <div style="display:flex;align-items:center;justify-content:space-between;">
      <strong>Menu</strong>
      <button class="mobile-menu-btn" id="menuClose" aria-label="Close menu" style="display:inline-grid;place-items:center;">
        <i data-lucide="x" aria-hidden="true"></i>
      </button>
    </div>
    <a href="#specialties">Browse</a>
    <a href="#">Log In</a>
    <button class="btn btn-primary" type="button">Sign Up</button>
  </aside>

  <main>
    <section class="hero container" id="home">
      <div class="hero-grid">
        <div>
          <span class="eyebrow"><i data-lucide="shield-check" aria-hidden="true"></i> Trusted by millions of patients</span>
          <h1>Find and book top doctors instantly.</h1>
          <p>
            MedBook helps you discover in-network doctors, dentists, and specialists near you. Compare verified reviews,
            see real-time availability, and book same-day appointments in minutes.
          </p>

          <form class="search-wrap" id="search-form" action="search-results.html" method="get" aria-label="Doctor search form">
            <div class="search-grid">
              <div class="input-group">
                <i data-lucide="search" aria-hidden="true"></i>
                <input id="searchInput" name="q" type="text" placeholder="Specialty, condition, or doctor" autocomplete="off" aria-label="Search specialty, condition, or doctor" required />
                <div class="suggestions" id="suggestions" role="listbox" aria-label="Search suggestions"></div>
              </div>
              <div class="input-group">
                <i data-lucide="map-pin" aria-hidden="true"></i>
                <input name="location" type="text" placeholder="City, ZIP, or neighborhood" aria-label="Location" required />
              </div>
              <button class="btn btn-primary" type="submit" aria-label="Search doctors">Find Care</button>
            </div>
          </form>
        </div>

        <div class="hero-art" aria-hidden="true">
          <div class="art-card">
            <div class="art-row"><strong>Next available</strong><span>Today</span></div>
            <div class="art-row"><span>Dermatology • 2.3 mi</span><span class="dot"></span></div>
          </div>
          <div class="art-card">
            <div class="art-row"><strong>4.8M+</strong><span>Verified reviews</span></div>
            <div class="art-row"><span>12,000+ providers</span><span>Nationwide</span></div>
          </div>
          <div class="art-card" style="margin-bottom:0;">
            <div class="art-row"><strong>100% free</strong><span>for patients</span></div>
            <div class="art-row"><span>Insurance-friendly search</span><span>✓</span></div>
          </div>
        </div>
      </div>
    </section>

    <section class="section container" id="specialties">
      <h2>Browse popular specialties</h2>
      <p class="lead">Explore common care categories and quickly connect with highly rated local providers.</p>
      <div class="card-grid">
        <a class="specialty-card" href="search-results.html?specialty=Primary%20Care" aria-label="Browse Primary Care doctors">
          <div class="spec-head"><span class="icon-chip"><i data-lucide="stethoscope"></i></span>Primary Care</div>
          <div>Routine checkups, preventive care, and ongoing health management.</div>
        </a>
        <a class="specialty-card" href="search-results.html?specialty=Dentist" aria-label="Browse Dentists">
          <div class="spec-head"><span class="icon-chip"><i data-lucide="smile"></i></span>Dentist</div>
          <div>Cleanings, oral exams, and treatment for tooth and gum concerns.</div>
        </a>
        <a class="specialty-card" href="search-results.html?specialty=Dermatologist" aria-label="Browse Dermatologists">
          <div class="spec-head"><span class="icon-chip"><i data-lucide="sparkles"></i></span>Dermatologist</div>
          <div>Skin, hair, and nail care for both medical and cosmetic needs.</div>
        </a>
        <a class="specialty-card" href="search-results.html?specialty=Psychiatrist" aria-label="Browse Psychiatrists">
          <div class="spec-head"><span class="icon-chip"><i data-lucide="brain"></i></span>Psychiatrist</div>
          <div>Mental health evaluations, medication management, and support.</div>
        </a>
        <a class="specialty-card" href="search-results.html?specialty=Eye%20Doctor" aria-label="Browse Eye Doctors">
          <div class="spec-head"><span class="icon-chip"><i data-lucide="eye"></i></span>Eye Doctor</div>
          <div>Vision exams, prescriptions, and eye health treatment options.</div>
        </a>
        <a class="specialty-card" href="search-results.html?specialty=Orthopedic%20Surgeon" aria-label="Browse Orthopedic Surgeons">
          <div class="spec-head"><span class="icon-chip"><i data-lucide="bone"></i></span>Orthopedic Surgeon</div>
          <div>Joint, bone, and muscle care for pain relief and recovery.</div>
        </a>
      </div>
    </section>

    <section class="section container" aria-label="Platform statistics">
      <h2>Healthcare booking, made reliable at scale</h2>
      <p class="lead">Trust signals that help patients book with confidence.</p>
      <div class="stats">
        <article class="stat"><strong>4.8M+</strong><span>verified patient reviews</span></article>
        <article class="stat"><strong>12,000+</strong><span>healthcare providers nationwide</span></article>
        <article class="stat"><strong>Same-day</strong><span>appointments available daily</span></article>
        <article class="stat"><strong>100% free</strong><span>for patients — always</span></article>
      </div>
    </section>

    <section class="section container" id="how-it-works">
      <h2>How MedBook works</h2>
      <p class="lead">Three simple steps from search to confirmed appointment.</p>
      <div class="steps">
        <article class="step">
          <div class="num">1</div>
          <h3>Search for a provider</h3>
          <p>Enter your specialty, condition, or doctor name with location and insurance preferences.</p>
        </article>
        <article class="step">
          <div class="num">2</div>
          <h3>Choose a time that works</h3>
          <p>Review real-time schedules and choose a same-day or next-day slot that fits your calendar.</p>
        </article>
        <article class="step">
          <div class="num">3</div>
          <h3>Book your appointment</h3>
          <p>Confirm in a few clicks and receive instant confirmation plus automated reminders.</p>
        </article>
      </div>
    </section>

    <section class="section container" id="testimonials">
      <h2>What patients are saying</h2>
      <div class="testimonials">
        <article class="quote">
          “I found a great dermatologist near my office and booked a same-day appointment during my lunch break. MedBook made it incredibly easy.”
          <b>Priya M., New York, NY</b>
        </article>
        <article class="quote">
          “As someone new to the city, MedBook helped me find a primary care doctor who accepts my insurance in under five minutes. Highly recommend!”
          <b>James T., Chicago, IL</b>
        </article>
        <article class="quote">
          “I was dreading finding a new dentist, but the verified reviews on MedBook gave me confidence. My appointment was exactly what I needed.”
          <b>Laura K., Austin, TX</b>
        </article>
      </div>
    </section>

    <section class="section container" id="mobile-app-promo">
      <div class="app-promo">
        <div>
          <h2>Your health, in your pocket</h2>
          <p class="lead">Download the MedBook app to search for doctors, manage appointments, and get reminders — all on the go. Available on iOS and Android.</p>
          <ul>
            <li>Book and manage appointments anywhere</li>
            <li>Get real-time appointment reminders</li>
            <li>Access visit history and provider details</li>
            <li>Read and leave verified reviews</li>
          </ul>
          <div class="store-buttons">
            <a href="#" class="store" aria-label="Download on App Store"><i data-lucide="smartphone"></i>Download on the App Store</a>
            <a href="#" class="store" aria-label="Get it on Google Play"><i data-lucide="play"></i>Get it on Google Play</a>
          </div>
        </div>
        <div class="hero-art" aria-hidden="true" style="padding:1rem;">
          <div class="art-card"><div class="art-row"><strong>Appointments</strong><span>Upcoming: 2</span></div></div>
          <div class="art-card"><div class="art-row"><strong>Reminder</strong><span>Tomorrow • 9:30 AM</span></div></div>
          <div class="art-card" style="margin-bottom:0;"><div class="art-row"><strong>Provider match</strong><span>In-network ✓</span></div></div>
        </div>
      </div>
    </section>
  </main>

  <footer id="footer">
    <div class="container">
      <div class="footer-grid">
        <div class="footer-col">
          <h3>For Patients</h3>
          <a href="#">Find a Doctor</a>
          <a href="#">Browse Specialties</a>
          <a href="#">Read Reviews</a>
          <a href="#">Insurance Guide</a>
        </div>
