  <script>
    const SUGGESTIONS = [
      'Primary Care',
      'Dentist',
      'Dermatologist',
      'Psychiatrist',
      'Eye Doctor',
      'Orthopedic Surgeon',
      'Back pain specialist',
      'Pediatrician',
      'OB-GYN',
      'Anxiety treatment'
    ];

    const searchInput = document.getElementById('searchInput');
    const suggestionsEl = document.getElementById('suggestions');

    function renderSuggestions(query) {
      const value = query.trim().toLowerCase();
      if (!value) {
        suggestionsEl.classList.remove('show');
        suggestionsEl.innerHTML = '';
        return;
      }

      const filtered = SUGGESTIONS.filter(item => item.toLowerCase().includes(value)).slice(0, 6);
      if (!filtered.length) {
        suggestionsEl.classList.remove('show');
        suggestionsEl.innerHTML = '';
        return;
      }

      suggestionsEl.innerHTML = filtered.map(item =>
        `<button type="button" class="suggestion-item" role="option">${item}</button>`
      ).join('');
      suggestionsEl.classList.add('show');
    }

    searchInput.addEventListener('input', (e) => renderSuggestions(e.target.value));

    suggestionsEl.addEventListener('click', (e) => {
      const btn = e.target.closest('.suggestion-item');
      if (!btn) return;
      searchInput.value = btn.textContent;
      suggestionsEl.classList.remove('show');
      suggestionsEl.innerHTML = '';
      searchInput.focus();
    });

    document.addEventListener('click', (e) => {
      if (!suggestionsEl.contains(e.target) && e.target !== searchInput) {
        suggestionsEl.classList.remove('show');
      }
    });

    const menuToggle = document.getElementById('menuToggle');
    const menuClose = document.getElementById('menuClose');
    const drawer = document.getElementById('mobileDrawer');
    const overlay = document.getElementById('drawerOverlay');

    function setDrawer(open) {
      drawer.classList.toggle('open', open);
      overlay.classList.toggle('show', open);
      menuToggle.setAttribute('aria-expanded', String(open));
      document.body.style.overflow = open ? 'hidden' : '';
    }

    menuToggle.addEventListener('click', () => setDrawer(true));
    menuClose.addEventListener('click', () => setDrawer(false));
    overlay.addEventListener('click', () => setDrawer(false));

    drawer.querySelectorAll('a, button').forEach((el) => {
      el.addEventListener('click', () => setDrawer(false));
    });

    lucide.createIcons();
  </script>
